'@
[System.IO.File]::WriteAllBytes($archive, [Convert]::FromBase64String($payload))
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne '4fcc18a3a5286713f1cf1a3282bf37ede022d5bec4c2a6444909b0e5fadcc4a9') { throw 'Pacote alterado. Nada foi aplicado/publicado.' }
Expand-Archive -LiteralPath $archive -DestinationPath $temp
$appScript = Join-Path $temp 'Preparar-App-Ativacao-1.05.ps1'
$serverScript = Join-Path $temp 'Publicar-Central-Ativacao-1.05.ps1'
if ((Get-FileHash -LiteralPath $appScript -Algorithm SHA256).Hash.ToLowerInvariant() -ne '4b7a60babf6006238265fc08375c5b6afd2569fa6b9297f0f5aa30ef898696a9') { throw 'Instalador Android alterado.' }
if ((Get-FileHash -LiteralPath $serverScript -Algorithm SHA256).Hash.ToLowerInvariant() -ne '6f0fe0f56717e989b6442d806034e0a101d77cd88542e40cc5bb888d99c0c9cf') { throw 'Instalador da central alterado.' }
$executor = (Get-Process -Id $PID).Path
& $executor -NoProfile -ExecutionPolicy Bypass -File $appScript -Projeto $Projeto -Verificar
if ($LASTEXITCODE -ne 0) { throw 'Fontes Android diferentes. Nada foi publicado ou aplicado. Envie a mensagem.' }
if ($Verificar) { exit 0 }
if ($SomentePreparar) {
    & $executor -NoProfile -ExecutionPolicy Bypass -File $serverScript -PastaDestino $PastaDestino -NaoPublicar
} else {
    & $executor -NoProfile -ExecutionPolicy Bypass -File $serverScript -PastaDestino $PastaDestino
}
if ($LASTEXITCODE -ne 0) { throw 'Central nao preparada/publicada. O projeto Android nao foi alterado.' }
if ($SomentePreparar) {
    & $executor -NoProfile -ExecutionPolicy Bypass -File $appScript -Projeto $Projeto -NaoCompilar
} else {
    & $executor -NoProfile -ExecutionPolicy Bypass -File $appScript -Projeto $Projeto
}
if ($LASTEXITCODE -ne 0) { throw 'Preparacao/compilacao Android falhou. Envie o erro. A central e compativel com o aplicativo anterior.' }
Write-Host 'Preparacao 1.05/code7 concluida. Instale por cima e teste o fluxo antes de publicar APKs.'
